import java.util.NavigableMap;
import java.util.TreeMap;

public class TreeMapRangeDemo {
    public static void main(String[] args) {
        NavigableMap<Double, String> priceBook = new TreeMap<>();

        // O(log n) insertions
        priceBook.put(99.99, "Basic Tier");
        priceBook.put(149.99, "Pro Tier");
        priceBook.put(199.99, "Enterprise Tier");

        // NavigableMap range and proximity queries
        Double targetPrice = 130.00;
        Double floorPrice = priceBook.floorKey(targetPrice);
        Double ceilingPrice = priceBook.ceilingKey(targetPrice);

        System.out.println("Closest floor price to $130: " + floorPrice); // 99.99
        System.out.println("Closest ceiling price to $130: " + ceilingPrice); // 149.99

        // Efficient sub-map view (backed by the original map)
        NavigableMap<Double, String> activeSubRange = priceBook.subMap(100.00, true, 200.00, true);
        System.out.println("SubMap size: " + activeSubRange.size());
    }
}
